  void* ptr1;
  ABSL_ASSERT_OK(rpc_channel()->Allocate(SharedMemorySize(), &ptr1));
  ASSERT_TRUE(IsWithinSharedMemoryRegion(ptr1));
  std::vector<uint8_t> buffer(SharedMemorySize() + 1024);
